def authorize_history(
    self, provided: str | None, required_permission: str | None
) -> str:
    """Authenticate one bearer credential for a gated route.

    Returns ``"ok"``, ``"unauthorized"`` (401) or ``"forbidden"`` (403).
    The configured static token has every power and is the *only*
    credential accepted for ``required_permission is None`` (the
    /v1/history/access management route). Otherwise an ``active``
    credential whose SHA-256 token hash matches authenticates, but only for
    routes whose permission its permission set covers; a wrong token, a
    missing/revoked credential or an insufficient permission set answers
    unauthorized/forbidden respectively. Never raises.
    """
    if not self.history_enabled:
        return "ok"
    expected = (
        f"Bearer {self.history_token}"
        if self.history_token is not None
        else None
    )
    provided_bytes = (
        provided.encode("utf-8", errors="replace")
        if isinstance(provided, str)
        else b""
    )
    if expected is not None and hmac.compare_digest(
        provided_bytes, expected.encode("utf-8")
    ):
        return "ok"
    # Only the static token may reach the credential-management route.
    if required_permission is None:
        return "unauthorized"
    credential = self.active_history_credential()
    if credential is None:
        return "unauthorized"
    if not isinstance(provided, str) or not provided.startswith("Bearer "):
        return "unauthorized"
    presented = provided[len("Bearer ") :]
    if not presented:
        return "unauthorized"
    presented_hash = hashlib.sha256(
        presented.encode("utf-8")
    ).hexdigest()
    if not hmac.compare_digest(
        presented_hash, credential["token_hash"]
    ):
        return "unauthorized"
    if required_permission not in credential["permissions"]:
        return "forbidden"
    return "ok"

@staticmethod
def _history_credential_response(credential: dict) -> dict:
    """A fresh response-shaped copy with the fixed key order."""
    return {key: credential[key] for key in HISTORY_CREDENTIAL_KEYS}

def active_history_credential(self) -> dict | None:
    """The active credential in response shape, or None when absent/revoked.

    Read under the store lock so the bearer gate never observes a
    half-rotated record. Only an ``active`` credential can authenticate;
    a revoked hash is reported as no credential (401).
    """
    with self.store.lock:
        credential = self.store.history_credential
        if credential is None or credential["status"] != HISTORY_CREDENTIAL_ACTIVE:
            return None
        response = self._history_credential_response(credential)
        response["permissions"] = list(credential["permissions"])
        return response

def manage_history_credential(self, payload: object) -> tuple[int, dict]:
    """POST /v1/history/access — rotate or revoke the history credential.

    The body must be a closed JSON object with exactly
    ``action, token, permissions, expected_version``. ``action`` is
    ``rotate`` or ``revoke``. A rotate carries a non-empty ``token`` and a
    non-empty, duplicate-free subset of read/update/export; a revoke
    carries ``null`` for both. ``expected_version`` is a non-boolean
    non-negative integer (the first create is made against version 0).
    Every shape defect answers 400/input before any state is consulted; a
    mismatched version answers 409/state. The first rotate creates the
    credential (201); a later rotate installs a fresh token hash and
    permission set at version+1 (200); a revoke keeps the version, token
    hash and permissions but flips status to revoked (200). Re-revoking an
    already-revoked credential at its version is an idempotent 200 with no
    new event or write. The credential section, the
    ``history_credential_changed`` event (action followed by the response)
    and the generation land in one atomic write; a failed save rolls the
    in-memory credential and event back.
    """
    if not self.history_enabled:
        return 404, {"ok": False, "error": "not found"}
    if (
        not isinstance(payload, dict)
        or set(payload) != set(self.HISTORY_ACCESS_FIELDS)
    ):
        return 400, {"ok": False, "error": "input"}
    action = payload["action"]
    if action not in ("rotate", "revoke"):
        return 400, {"ok": False, "error": "input"}
    expected_version = payload["expected_version"]
    if (
        isinstance(expected_version, bool)
        or not isinstance(expected_version, int)
        or expected_version < 0
    ):
        return 400, {"ok": False, "error": "input"}
    token = payload["token"]
    permissions = payload["permissions"]
    if action == "rotate":
        if not isinstance(token, str) or not token:
            return 400, {"ok": False, "error": "input"}
        # Validate every element is a string before hashing them into a
        # set: an unhashable (e.g. nested list/dict) permission must be a
        # plain 400/input, never a TypeError/500.
        if (
            not isinstance(permissions, list)
            or not permissions
            or any(
                not isinstance(permission, str)
                for permission in permissions
            )
            or len(set(permissions)) != len(permissions)
            or any(
                permission not in HISTORY_PERMISSION_SET
                for permission in permissions
            )
        ):
            return 400, {"ok": False, "error": "input"}
        ordered_permissions = [
            permission
            for permission in HISTORY_PERMISSION_ORDER
            if permission in permissions
        ]
    else:  # revoke: both token and permissions must be JSON null.
        if token is not None or permissions is not None:
            return 400, {"ok": False, "error": "input"}
        ordered_permissions = None

    with self.store.lock:
        current = self.store.history_credential
        if current is None:
            # The first operation must be a rotate against version 0; a
            # revoke of a never-created credential, or any other expected
            # version, is a state conflict rather than a format error.
            if action != "rotate" or expected_version != 0:
                return 409, {"ok": False, "error": "state"}
            created = True
        else:
            if expected_version != current["version"]:
                return 409, {"ok": False, "error": "state"}
            if (
                action == "revoke"
                and current["status"] == HISTORY_CREDENTIAL_REVOKED
            ):
                # Idempotent re-revoke: report the unchanged revoked
                # record with no event and no write (a second revoke event
                # would be rejected on recovery).
                return 200, self._history_credential_response(current)
            created = False

        previous = current
        if action == "rotate":
            token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
            new_version = 0 if current is None else current["version"] + 1
            credential = {
                "version": new_version,
                "token_hash": token_hash,
                "permissions": ordered_permissions,
                "status": HISTORY_CREDENTIAL_ACTIVE,
            }
        else:
            credential = self._history_credential_response(current)
            credential["status"] = HISTORY_CREDENTIAL_REVOKED
        self.store.history_credential = credential
        # Event payload: action followed by the response document, in the
        # response key order.
        self.store.append_audit_event(
            EVENT_HISTORY_CREDENTIAL_CHANGED,
            {
                "action": action,
                "version": credential["version"],
                "token_hash": credential["token_hash"],
                "permissions": list(credential["permissions"]),
                "status": credential["status"],
            },
        )
        try:
            self.store.save()
        except Exception:
            # Roll the in-memory credential, its event and the generation
            # back together; no half state survives an unserviced write.
            self.store.history_credential = previous
            self.store.truncate_audit_events(1)
            return 500, {"ok": False, "error": "io"}
        return (
            201 if created else 200
        ), self._history_credential_response(credential)

def _history_heads(self) -> tuple[str | None, str | None]:
    """Current (trust_head, history_head); null for a not-yet-created file.

    Caller must already hold the store lock and both file-path locks.
    Raises OSError for an ``io``-class read failure or
    ``_HistoryFileError`` for a strict-verification (``state``) defect, so
    callers can map the outcome onto the 500/409 contract.
    """
    from . import light_client

    inspection = light_client.inspect_history_files(
        self.history_path, self.history_trust_path
    )
    if not inspection.get("ok"):
        category = inspection.get("error")
        if category == "io":
            raise OSError(
                inspection.get("path"),
                "managed history file unreadable",
            )
        raise LedgerService._HistoryFileError(
            category or "state", inspection.get("path")
        )
    return inspection["trust_head"], inspection["history_head"]

class _HistoryFileError(Exception):
    """A managed history file failed strict verification mid-request."""

    def __init__(self, category: str, path: str | None) -> None:
        self.category = category
        self.path = path
        super().__init__(f"{category}: {path}")

    # absent from the registry is orphan corruption (fatal, never pruned),
    # a present section missing a registry source is corruption, and each
    # shared source's entries must equal the reconstruction exactly.
    for source in history:
        if source not in trust_sources:
            fail(
                f"source_key_history names unknown trust source {source!r}"
            )
        if history[source] != expected[source]:
            fail(
                f"source_key_history for {source!r} does not match its "
                "registry record and audit events"
            )
    for source in expected:
        if source not in history:
            # Current code writes one history entry per registered source;
            # a present section missing a registry source is corruption
            # rather than a legacy migration.
            fail(f"source_key_history is missing source {source!r}")
    return history, False

@staticmethod
def _parse_persisted_allowlist(raw: object, path: str) -> dict[str, int]:
    """Strictly parse the keyless ``{source: expires_at}`` allowlist."""
    if raw is None:
        return {}
    if not isinstance(raw, dict):
        raise StateRecoveryError(path, "'allowlist' must be a JSON object")
    allowlist: dict[str, int] = {}
    for source, expires_at in raw.items():
        if not isinstance(source, str) or not source:
            raise StateRecoveryError(path, "allowlist source must be a non-empty string")
        if isinstance(expires_at, bool) or not isinstance(expires_at, int):
            raise StateRecoveryError(
                path, f"allowlist entry {source!r} expires_at must be an integer"
            )
        allowlist[source] = expires_at
    return allowlist

@staticmethod
def _validate_history_credential_shape(
    raw: object, path: str, *, where: str
) -> dict:
    """Validate one ``{version, token_hash, permissions, status}`` record.

    Shared by the persisted snapshot section and the
    ``history_credential_changed`` audit payload. ``version`` is a
    non-boolean non-negative integer (starting at 0), ``token_hash`` is a
    64-char lowercase hex SHA-256 digest, ``permissions`` is a non-empty
    duplicate-free list drawn from read/update/export and ``status`` is
    active/revoked. Any defect is snapshot corruption. Returns a fresh dict
    in the contract key order.
    """
    label = f"{where} history credential"
    if not isinstance(raw, dict):
        raise StateRecoveryError(path, f"{label} must be a JSON object")
    if set(raw.keys()) != set(HISTORY_CREDENTIAL_KEYS):
        raise StateRecoveryError(
            path,
            f"{label} must have exactly the keys {HISTORY_CREDENTIAL_KEYS}",
        )
    version = raw["version"]
    if isinstance(version, bool) or not isinstance(version, int) or version < 0:
        raise StateRecoveryError(
            path, f"{label} version must be a non-negative integer"
        )
    token_hash = raw["token_hash"]
    if not crypto.is_hex64(token_hash):
        raise StateRecoveryError(
            path, f"{label} token_hash must be 64 lowercase hex characters"
        )
    permissions = raw["permissions"]
    if (
        not isinstance(permissions, list)
        or not permissions
        # Check element types before building a set, so an unhashable
        # (nested list/dict) permission is reported as corruption rather
        # than escaping as a TypeError.
        or any(not isinstance(permission, str) for permission in permissions)
        or len(set(permissions)) != len(permissions)
        or any(
            permission not in HISTORY_PERMISSION_SET
            for permission in permissions
        )
    ):
        raise StateRecoveryError(
            path,
            f"{label} permissions must be a non-empty duplicate-free "
            "subset of read/update/export",
        )
    status = raw["status"]
    if status not in (
        HISTORY_CREDENTIAL_ACTIVE,
        HISTORY_CREDENTIAL_REVOKED,
    ):
        raise StateRecoveryError(
            path, f"{label} status must be active or revoked"
        )
    return {
        "version": version,
        "token_hash": token_hash,
        # Persist in the fixed read/update/export response order.
        "permissions": [
            permission
            for permission in HISTORY_PERMISSION_ORDER
            if permission in permissions
        ],
        "status": status,
    }

def _parse_persisted_history_credential(
    self, raw: object, audit_events: list[dict], path: str
) -> dict | None:
    """Strictly parse the persisted history credential section.

    The section is optional (a snapshot written before the feature omits
    it). A present section must be structurally valid and exactly
    reproducible by replaying the durable ``history_credential_changed``
    events: the first rotate creates the version-0 active credential, each
    later rotate bumps the version and installs a fresh token hash /
    permission set, and the terminal revoke keeps version/hash/permissions
    while flipping status to revoked. Any drift is corruption.
    """
    if raw is None:
        credential = None
    else:
        credential = self._validate_history_credential_shape(
            raw, path, where="persisted"
        )
    # Replay the change events independently of the stored section.
    replayed: dict | None = None
    for event in audit_events:
        if event.get("kind") != EVENT_HISTORY_CREDENTIAL_CHANGED:
            continue
        action = event.get("action")
        if action not in ("rotate", "revoke"):
            raise StateRecoveryError(
                path,
                f"history_credential_changed event "
                f"{event.get('event_id')} has an invalid action",
            )
        change = self._validate_history_credential_shape(
            {
                "version": event.get("version"),
                "token_hash": event.get("token_hash"),
                "permissions": event.get("permissions"),
                "status": event.get("status"),
            },
            path,
            where=f"audit event {event.get('event_id')}",
        )
        if action == "rotate":
            if change["status"] != HISTORY_CREDENTIAL_ACTIVE:
                raise StateRecoveryError(
                    path,
                    f"history_credential_changed event "
                    f"{event.get('event_id')} rotate must leave the "
                    "credential active",
                )
            if replayed is None:
                if change["version"] != 0:
                    raise StateRecoveryError(
                        path,
                        "first history_credential_changed rotate must "
                        "create version 0",
                    )
            else:
                if change["version"] != replayed["version"] + 1:
                    raise StateRecoveryError(
                        path,
                        f"history_credential_changed event "
                        f"{event.get('event_id')} version must be exactly "
                        "one greater than the previous version",
                    )
            replayed = change
        else:  # revoke
            if change["status"] != HISTORY_CREDENTIAL_REVOKED:
                raise StateRecoveryError(
                    path,
                    f"history_credential_changed event "
                    f"{event.get('event_id')} revoke must leave the "
                    "credential revoked",
                )
            if replayed is None:
                raise StateRecoveryError(
                    path,
                    f"history_credential_changed event "
                    f"{event.get('event_id')} revokes a credential that "
                    "was never created",
                )
            if replayed["status"] == HISTORY_CREDENTIAL_REVOKED:
                raise StateRecoveryError(
                    path,
                    f"history_credential_changed event "
                    f"{event.get('event_id')} revokes an already-revoked "
                    "credential",
                )
            if (
                change["version"] != replayed["version"]
                or change["token_hash"] != replayed["token_hash"]
                or change["permissions"] != replayed["permissions"]
            ):
                raise StateRecoveryError(
                    path,
                    f"history_credential_changed event "
                    f"{event.get('event_id')} revoke must preserve "
                    "version, token_hash and permissions",
                )
            replayed = change
    if credential != replayed:
        raise StateRecoveryError(
            path,
            "persisted history_credential does not match the credential "
            "reconstructed from history_credential_changed events",
        )
    return credential

